WITH with_windows AS (SELECT id, full_name, salary, is_remote, LEAD(salary) OVER w_ordered AS next_salary, LAG(salary) OVER w_ordered AS prev_salary, ROW_NUMBER() OVER w_ordered AS event_seq, PERCENT_RANK() OVER w_running AS salary_percent_rank FROM employees WINDOW w_ordered AS (PARTITION BY dept_id, level ORDER BY hire_date, id), w_running AS (ORDER BY salary DESC)) SELECT id, is_remote, prev_salary, event_seq FROM with_windows ORDER BY prev_salary DESC NULLS LAST;
